<?php /** @var array $store */ ?>
<section class="hero"><div class="container hero-grid"><div><p class="eyebrow">Reusable e-commerce foundation</p><h1><?=e($store['tagline'])?></h1><p class="hero-body"><?=e($store['description'])?></p><div class="actions"><a class="button primary" href="/products">Shop products</a><a class="button secondary" href="/contact">Contact</a></div></div><aside class="panel"><span class="hero-mark" aria-hidden="true">S</span><h2>Built around a real checkout flow.</h2><p>Products and prices are server-side, orders are stored locally, payments use Stripe Checkout, and confirmation delivery uses SMTP email.</p></aside></div></section>
<section class="section"><div class="container"><div class="section-heading"><p class="eyebrow">Featured products</p><h2>Simple catalogue, ready to customise.</h2></div><div class="product-grid"><?php foreach(array_slice(products($store),0,4) as $product):?><article class="product-card"><?php if(($image=product_image($store,$product['slug']))!==null):?><a class="product-image-link" href="/products/<?=e($product['slug'])?>"><img class="product-image" src="<?=e(url($image))?>" alt="<?=e($product['name'])?>" loading="lazy" decoding="async"></a><?php endif;?><p class="eyebrow"><?=e($product['stock'])?> in stock</p><h3><a href="/products/<?=e($product['slug'])?>"><?=e($product['name'])?></a></h3><p><?=e($product['summary'])?></p><p class="price"><?=e(money((int)$product['price_pence'],$store))?></p><form method="post" action="/cart"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add"><input type="hidden" name="slug" value="<?=e($product['slug'])?>"><button class="button primary" type="submit">Add to basket</button></form></article><?php endforeach;?></div></div></section>
<section class="section tinted"><div class="container"><div class="feature-list"><div class="feature"><strong>01</strong><div><h3>Server-side pricing</h3><p>Cart totals and Stripe line items come from the configured product catalogue rather than browser-supplied prices.</p></div></div><div class="feature"><strong>02</strong><div><h3>Hosted payment</h3><p>Stripe Checkout keeps card entry outside this application and returns customers to the configured success or cancel route.</p></div></div><div class="feature"><strong>03</strong><div><h3>Return-page verification</h3><p>The server retrieves the completed Checkout Session with the secret key and verifies payment status, order reference, amount and currency before recording the order as paid.</p></div></div></div></div></section>
